// ───────────────────────────── store prices (v18.4, 22 Oct 2026) ─────────────────────────────
// A price for one store only (e.g. new prices at Gulshan first). Bills at that store use it; other stores keep the
// Products price. "Apply to all stores" copies them into Products (price history + QueueBuster list) and closes them.
const SP_TAB = 'Store Prices', SP_H = ['SKU', 'Product', 'Location', 'Selling ₹', 'MRP ₹', 'Old selling ₹', 'Old MRP ₹', 'Source', 'Set by', 'Set at', 'Status'];
function storePrices_() {
  const hit = cget_('sprices'); if (hit) return hit;
  const o = {};
  xrows_(SP_TAB, SP_H).forEach(r => { if (s_(r[10]) === 'Active' && n_(r[3])) (o[s_(r[2])] = o[s_(r[2])] || {})[s_(r[0])] = { sell: n_(r[3]), mrp: n_(r[4]) }; });
  cput_('sprices', o, 600);
  return o;
}
function spChanged_() { cdel_('sprices'); PropertiesService.getScriptProperties().setProperty('PRODUCTS_VER', String(Date.now())); }
/** d = {location, source, items:[{sku, sell, mrp}]} – replaces the active store price of each item at that store. */
function setStorePrices_(d, user) {
  const loc = s_(d && d.location);
  if (LOCATIONS.indexOf(loc) < 0 || loc === CENTRAL) throw new Error('Pick the store.');
  const pm = prodMap_(), now = new Date(), add = [], want = {};
  (d.items || []).forEach(it => {
    const r = pm[s_(it.sku)]; if (!r) throw new Error('Unknown product ' + it.sku);
    const sell = round2_(n_(it.sell)), mrp = round2_(n_(it.mrp)) || n_(r[PC.mrp]);
    if (!(sell > 0)) throw new Error(s_(r[PC.name]) + ': enter the selling price.');
    if (mrp && sell > mrp) throw new Error(s_(r[PC.name]) + ': selling price is higher than MRP.');
    want[s_(it.sku)] = 1;
    add.push([s_(it.sku), s_(r[PC.name]), loc, sell, mrp || '', n_(r[PC.sell]) || '', n_(r[PC.mrp]) || '', txt_(d.source, 120), user ? user.name : 'Owner', now, 'Active']);
  });
  if (!add.length) throw new Error('No prices.');
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const sh = xtab_(SP_TAB, SP_H), all = xrows_(SP_TAB, SP_H);
    all.forEach((r, i) => { if (s_(r[2]) === loc && want[s_(r[0])] && s_(r[10]) === 'Active') sh.getRange(i + 2, 11).setValue('Replaced'); });
    sh.getRange(sh.getLastRow() + 1, 1, add.length, SP_H.length).setValues(add);
  } finally { lock.releaseLock(); }
  spChanged_();
  return { set: add.length, list: storePriceList_() };
}
function storePriceList_() {
  const pm = prodMap_(), out = {};
  const sp = (cdel_('sprices'), storePrices_());
  Object.keys(sp).forEach(loc => out[loc] = Object.keys(sp[loc]).map(sku => {
    const r = pm[sku] || [];
    return { sku: sku, name: s_(r[PC.name]), unit: s_(r[PC.unit]), sell: sp[loc][sku].sell, mrp: sp[loc][sku].mrp, baseSell: n_(r[PC.sell]), baseMrp: n_(r[PC.mrp]) };
  }).sort((a, b) => a.name.localeCompare(b.name)));
  return out;
}
/** Make this store's prices the price everywhere (Products), then close them. */
function applyStorePrices_(d, user) {
  const loc = s_(d && d.location), sp = (cdel_('sprices'), storePrices_())[loc] || {};
  const skus = Object.keys(sp); if (!skus.length) throw new Error('No store prices at ' + loc + '.');
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const psh = tab_('products'), prows = psh.getRange(2, 1, psh.getLastRow() - 1, H.products.length).getValues(), now = new Date(), hist = [];
    prows.forEach(r => {
      const p = sp[s_(r[PC.sku])]; if (!p) return;
      const os = n_(r[PC.sell]), om = n_(r[PC.mrp]);
      r[PC.sell] = p.sell; if (p.mrp) r[PC.mrp] = p.mrp; r[PC.margin] = margin_(n_(r[PC.cost]), p.sell); r[PC.updated] = now;
      if (os !== p.sell || om !== n_(r[PC.mrp])) hist.push([now, s_(r[PC.sku]), r[PC.name], n_(r[PC.cost]) || '', n_(r[PC.cost]) || '', os || '', p.sell, om || '', n_(r[PC.mrp]) || '', 'Store prices of ' + loc + ' applied to all stores', user ? user.name : 'Owner']);
    });
    psh.getRange(2, 1, prows.length, H.products.length).setValues(prows);
    append_('prices', hist);
  } finally { lock.releaseLock(); }
  safe_('Products → Night Closing', syncProductsToNightClosing);
  const sh = xtab_(SP_TAB, SP_H), all = xrows_(SP_TAB, SP_H);
  all.forEach((r, i) => { if (s_(r[2]) === loc && s_(r[10]) === 'Active') sh.getRange(i + 2, 11).setValue('Applied to all stores ' + ymd_(new Date())); });
  spChanged_();
  return { applied: skus.length, list: storePriceList_() };
}
function clearStorePrices_(d) {
  const loc = s_(d && d.location), sku = s_(d && d.sku);
  const sh = xtab_(SP_TAB, SP_H), all = xrows_(SP_TAB, SP_H); let n = 0;
  all.forEach((r, i) => { if (s_(r[2]) === loc && (!sku || s_(r[0]) === sku) && s_(r[10]) === 'Active') { sh.getRange(i + 2, 11).setValue('Removed'); n++; } });
  spChanged_();
  return { removed: n, list: storePriceList_() };
}

