async function storePriceSheet(loc) {
  const r = await run('Loading…', () => call('storePrices')), list = r[loc] || [];
  const m = modal('Store-only prices – ' + loc, '<div class="tscroll"><table class="t"><tr><th>Product</th><th class="n">Normal</th><th class="n">Here</th><th class="n">MRP here</th><th></th></tr>' +
    list.map(x => '<tr><td>' + esc(x.name.replace(/^Nutvique\s+/, '')) + '</td><td class="n">' + inr(x.baseSell, 0) + '</td><td class="n"><b>' + inr(x.sell, 0) + '</b></td><td class="n">' + inr(x.mrp, 0) + '</td><td><button class="btn sm ghost" data-spx="' + esc(x.sku) + '">×</button></td></tr>').join('') + '</table></div>' +
    '<button class="btn ghost block" id="spclr" style="margin-top:12px">Remove all store-only prices here</button>', { wide: true });
  $$('[data-spx]', m).forEach(b => b.onclick = async e => { if (!confirmTwice(e.target)) return; await run('Removing…', () => call('clearStorePrices', { location: loc, sku: b.dataset.spx })); await refresh(true); m.close(); storePriceSheet(loc); });
  $('#spclr', m).onclick = async e => { if (!confirmTwice(e.target)) return; await run('Removing…', () => call('clearStorePrices', { location: loc })); await refresh(true); m.close(); viewMore(); };
}

